/**
 * Editor for `nextsaas/post-article-content`.
 *
 * The article body is the post's own content, so there is nothing to edit in place:
 * the canvas previews the rendered markup and the sidebar carries the two
 * destinations and the table-of-contents wording. Headings and their anchors are
 * generated by the renderer, so an editor never manages them.
 */

import { InspectorControls } from '@wordpress/block-editor';
import { PanelBody, TextControl } from '@wordpress/components';
import { __ } from '@wordpress/i18n';

import BlockPreview from '../../resources/ts/editor/block-preview';
import RichTextOverlay, {
	type RichTextTarget,
} from '../../resources/ts/editor/rich-text-overlay';
import { urlHelpWithStructuralNote } from '../../resources/ts/editor/url-help';
import type { EditorEditProps } from '../../resources/ts/editor/types';
import type { PostArticleContentAttributes } from './types';

/** The values the renderer marks inside the article shell. */
const targets: RichTextTarget[] = [
	{ path: 'tocLabel', label: __('Table of contents label', 'nextsaas') },
	{ path: 'primaryLabel', label: __('Primary link label', 'nextsaas') },
	{ path: 'secondaryLabel', label: __('Secondary link label', 'nextsaas') },
];

export default function Edit({
	attributes,
	setAttributes,
	isSelected,
}: EditorEditProps<PostArticleContentAttributes>): JSX.Element {
	return (
		<>
			<InspectorControls>
				<PanelBody title={__('Destinations', 'nextsaas')} initialOpen>
					<TextControl
						label={__('Primary link URL', 'nextsaas')}
						help={urlHelpWithStructuralNote}
						value={attributes.primaryUrl ?? ''}
						onChange={(primaryUrl) => setAttributes({ primaryUrl })}
					/>
					<TextControl
						label={__('Secondary link URL', 'nextsaas')}
						help={urlHelpWithStructuralNote}
						value={attributes.secondaryUrl ?? ''}
						onChange={(secondaryUrl) => setAttributes({ secondaryUrl })}
					/>
				</PanelBody>

				<PanelBody title={__('Table of contents', 'nextsaas')} initialOpen={false}>
					<TextControl
						label={__('Visible label', 'nextsaas')}
						value={attributes.tocLabel ?? ''}
						onChange={(tocLabel) => setAttributes({ tocLabel })}
					/>
					<TextControl
						label={__('Accessible name', 'nextsaas')}
						help={__(
							'The aside’s own label. Shown only when the article has more than one heading.',
							'nextsaas'
						)}
						value={attributes.tocAriaLabel ?? ''}
						onChange={(tocAriaLabel) => setAttributes({ tocAriaLabel })}
					/>
				</PanelBody>
			</InspectorControls>

			<BlockPreview block="nextsaas/post-article-content" attributes={attributes} />

			<RichTextOverlay
				targets={targets}
				attributes={attributes}
				setAttributes={(next) =>
					setAttributes(next as Partial<PostArticleContentAttributes>)
				}
				isSelected={isSelected}
			/>
		</>
	);
}
